            presentationId: string;
            /** @enum {string} */
            type: "descuento_porcentual" | "precio_especial" | "pague_x_lleve_y";
            percent?: number;
            specialPriceCop?: number;
            payX?: number;
            takeY?: number;
            conditions: components["schemas"]["PromotionConditions"];
            /** Format: date */
            validFrom: string;
            /** Format: date */
            validUntil: string;
